package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerFile *os.File
var scanner *bufio.Scanner
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func formatAmtEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZ9.99", false)
}
func formatBalEd(d decimal.Decimal) string {
	return formatEdited(d, "-Z,ZZZ,ZZ9.99", true)
}
func formatTotEd(d decimal.Decimal) string {
	return formatEdited(d, "-ZZZ,ZZZ,ZZ9.99", true)
}

// Generic numeric-edited formatter.
// picture examples: "ZZ,ZZ9.99" , "-Z,ZZZ,ZZ9.99" , "-ZZZ,ZZZ,ZZ9.99"
// If signed, first char is '-' sign placeholder.
func formatEdited(d decimal.Decimal, pic string, signed bool) string {
	width := len(pic)
	// Determine scale from pic (digits after '.')
	dotIdx := strings.Index(pic, ".")
	scale := 0
	if dotIdx >= 0 {
		scale = width - dotIdx - 1
	}
	// Round / truncate? MOVE to edited field: just format value (scale truncation handled by caller storage)
	// Ensure d has correct scale for display; format with sign handling
	neg := d.IsNegative()
	abs := d
	if neg {
		abs = abs.Neg()
	}
	// We need to represent abs rounded/truncated to scale. The source fields are already at scale 2.
	// Ensure we truncate/round appropriately - but direct formatting: use Abs value as decimal.
	// abs may have more than scale decimals; COBOL MOVE would handle size? We format with fixed decimals.
	abs = abs.Truncate(int32(scale))

	// Build integer and fractional parts
	// Use string representation
	s := abs.StringFixed(int32(scale)) // e.g. "1234.56"
	// Split
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		}
		// pad frac
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		}
	} else {
		intPartStr = s
	}

	// For integer part, detect overflow: if more digits than picture allows for integer positions, keep low-order digits
	// Count integer placeholders: number of Z/9 before dot (excluding commas and sign)
	intPic := pic
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
	}
	// Remove commas from intPic to count digit slots, also remove sign char if present
	intPicNoComma := strings.ReplaceAll(intPic, ",", "")
	if signed {
		if len(intPicNoComma) > 0 && intPicNoComma[0] == '-' {
			intPicNoComma = intPicNoComma[1:]
		}
	}
	numIntSlots := len(intPicNoComma) // number of Z/9 positions for integer
	if len(intPartStr) > numIntSlots {
		intPartStr = intPartStr[len(intPartStr)-numIntSlots:]
	}
	intPartStr = strings.Repeat("0", numIntSlots-len(intPartStr)) + intPartStr

	// Now build output buffer of width characters, initially fill with picture literals
	// We'll construct formatted integer section character by character from rightmost digit
	// We need to map digit positions to picture positions
	// Iterate picture integer section from right to left, filling digits
	out := []byte(pic)

	// Determine integer section range in pic
	intStart := 0
	if signed {
		intStart = 1 // skip sign placeholder at 0
	}
	intEnd := dotIdx
	if dotIdx < 0 {
		intEnd = width
	}
	// Fill digits: walk pic positions from intEnd-1 down to intStart, filling from intPartStr rightmost
	digitIdx := len(intPartStr) - 1
	for i := intEnd - 1; i >= intStart; i-- {
		c := pic[i]
		if c == 'Z' || c == '9' {
			out[i] = '0' + (intPartStr[digitIdx] - '0')
			digitIdx--
		} else if c == ',' {
			out[i] = ','
		}
	}
	// Fractional part
	if dotIdx >= 0 {
		out[dotIdx] = '.'
		for i := dotIdx + 1; i < width; i++ {
			// pic[i] should be '9'
			pos := i - (dotIdx + 1)
			if pos < len(fracPartStr) {
				out[i] = fracPartStr[pos]
			} else {
				out[i] = '0'
			}
		}
	}
	// Apply Z suppression: leading zeros become spaces
	// For signed pictures, sign char handling: if negative, '+'? In COBOL '-' picture: '-' if negative else space
	signChar := byte(' ')
	if neg {
		signChar = '-'
	}
	if signed {
		out[0] = signChar
	}
	// Z suppression: iterate integer part left to right, turning '0' and ',' accordingly until first non-zero or '9' position
	// Rule: Z replaces leading zero with space, commas inside suppressed zone also become spaces.
	suppressing := true
	for i := intStart; i < intEnd; i++ {
		c := pic[i]
		if c == ',' {
			if suppressing {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if c == 'Z' {
			if suppressing {
				if out[i] == '0' {
					out[i] = ' '
				} else {
					suppressing = false
				}
			} else {
				// already out of suppression, keep digit
			}
		} else if c == '9' {
			suppressing = false
		}
	}
	return string(out)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseLedgerRec(line string) LedgerRec {
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	}
	if len(line) > 14 {
		line = line[:14]
	}
	brBranch := line[0:2]
	brAcct := line[2:6]
	brType := line[6:7]
	amtStr := line[7:14]
	// amtStr is 7 digits, implied 2 decimals
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		amtStr = "0"
	}
	// digits only
	n := int64(0)
	for _, ch := range amtStr {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	amt := decimal.New(n, -2)
	return LedgerRec{
		BrBranch: brBranch,
		BrAcct:   brAcct,
		BrType:   brType,
		BrAmt:    amt,
	}
}

func READ_PARA() {
	if scanner.Scan() {
		line := scanner.Text()
		ledgerRec = parseLedgerRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func POST_PARA() {
	WsAmtEd = formatAmtEd(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func GRAND_PARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	// PIC 99 : zero-padded to 2 digits? But COBOL DISPLAY of numeric field: for unedited, zero-padded.
	// Original: DISPLAY "SKIPPED: " WS-SKIPPED. WS-SKIPPED is PIC 99, will display as 2 digits.
	// However Go spec says unedited numeric DISPLAY prints zero-padded to its digit count.
	// So we need to format as 2 digits with leading zero.
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Printf("SKIPPED: %s\n", skippedStr)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	ledgerFile = f
	scanner = bufio.NewScanner(f)
	// allow long lines
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)

	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	ledgerFile.Close()
	GRAND_PARA()
}
